(()=>{'use strict';const {$,$$,esc:E}=Q;let seq=0,rows=[],page=1,last=1,mode='browse',loaded=false,busy=false,previous=new Set(),catalogue=[];const H='https://hadeethenc.com/api/v1/';const status=s=>$('#hadithStatus').textContent=s;const controls=()=>{$('#hadithCategory').disabled=busy;$('#saveBatch').disabled=!rows.length||busy;$('#shuffleHadith').disabled=busy;$('#browseHadith').disabled=busy;$('#hadithPrev').disabled=busy||mode==='shuffle'||page<=1;$('#hadithNext').disabled=busy||mode==='shuffle'||page>=last;$('#hadithPage').textContent=mode==='shuffle'?Q.t('shuffle'):Q.t('page')+' '+page+' / '+last;};
async function categories(){const lang=Q.lang;try{const z=Q.unbox(await Q.json(H+'categories/list/?language='+lang));if(lang!==Q.lang)return;catalogue=Array.isArray(z)?z:[];const current=$('#hadithCategory').value;$('#hadithCategory').innerHTML=`<option value="">${E(Q.t('all'))}</option>`+catalogue.map(c=>`<option value="${E(c.id)}">${E(c.title)}</option>`).join('');$('#hadithCategory').value=current;}catch{if(!$('#hadithCategory').options.length)$('#hadithCategory').innerHTML=`<option value="">${E(Q.t('all'))}</option>`;}}
async function list(p,lang,category){const params=new URLSearchParams({language:lang,page:String(p),per_page:'6'});if(category)params.set('category_id',category);const z=await Q.json(H+'hadeeths/list/?'+params);const data=Array.isArray(z)?z:(z.data||z.result||[]);if(!Array.isArray(data))throw Error('Invalid hadith list');return {data,meta:z.meta||{last_page:1}};}
async function detail(id,lang){const d=Q.unbox(await Q.json(H+'hadeeths/one/?id='+encodeURIComponent(id)+'&language='+lang));if(!d||!d.id||!d.hadeeth)throw Error('Full hadith unavailable');return {...d,_language:lang,_savedAt:new Date().toISOString(),_source:`https://hadeethenc.com/${lang}/browse/hadith/${d.id}`};}
function render(){const q=$('#hadithFilter').value.toLowerCase(),f=Q.saved();$('#hadithGrid').innerHTML=rows.filter(h=>[h.title,h.hadeeth].join(' ').toLowerCase().includes(q)).map(h=>`<article class="hadith-card" data-id="${E(h.id)}"><div class="hadith-grade">${E(Q.t('grade'))}: ${E(Q.plain(h.grade)||Q.t('noGrade'))}</div><h3 lang="${h._language}">${E(Q.plain(h.title))}</h3><p lang="${h._language}">${E(Q.plain(h.hadeeth))}</p>${h.attribution?`<small>${E(Q.plain(h.attribution))}</small>`:''}<details><summary>${E(Q.t('explanation'))}</summary><p lang="${h._language}">${E(Q.plain(h.explanation)||Q.t('notAvailable'))}</p>${Array.isArray(h.hints)?h.hints.map(t=>`<p lang="${h._language}">${E(Q.plain(t))}</p>`).join(''):''}</details>${h.reference?`<small>${E(Q.plain(h.reference))}</small>`:''}<small>HadeethEnc | ${E(h._language)} | ${E(h._savedAt.slice(0,10))}${h.version?' | v'+E(h.version):''}</small><a href="${E(h._source)}" target="_blank" rel="noopener">${E(Q.t('source'))} / ${E(Q.t('refresh'))}</a><div><button class="btn" data-save-hadith="${E(h.id)}" aria-pressed="${f.includes(String(h.id))}">${E(Q.t(f.includes(String(h.id))?'remove':'save'))}</button></div></article>`).join('');controls();}
async function load(newMode='browse',requested=1){if(busy)return;busy=true;mode=newMode;loaded=true;const token=++seq,lang=Q.lang,category=$('#hadithCategory').value;status(Q.t('loading'));rows=[];render();try{let ids=[];if(mode==='favorites'){last=Math.max(1,Math.ceil(Q.saved().length/6));page=Math.max(1,Math.min(requested,last));ids=Q.saved().slice((page-1)*6,page*6);}else{let result=await list(newMode==='shuffle'?1:requested,lang,category);last=Number(result.meta.last_page)||1;page=newMode==='shuffle'?Math.floor(Math.random()*last)+1:requested;if(page!==(newMode==='shuffle'?1:requested))result=await list(page,lang,category);let available=Q.unique(result.data).filter(x=>!Array.isArray(x.translations)||x.translations.includes(lang));if(mode==='shuffle'){let unseen=available.filter(x=>!previous.has(String(x.id)));if(unseen.length<6&&last>1){const other=await list(page===last?1:page+1,lang,category);unseen=Q.unique([...unseen,...other.data.filter(x=>!previous.has(String(x.id))&&(!Array.isArray(x.translations)||x.translations.includes(lang)))]);}available=Q.shuffle(unseen.length?unseen:available);}ids=available.slice(0,6).map(x=>String(x.id));}const result=await Promise.allSettled(ids.map(async id=>{try{return await detail(id,lang);}catch(e){const snapshot=await Q.idb('get',`hadith:${id}:${lang}`).catch(()=>null);if(snapshot)return snapshot;throw e;}}));if(token!==seq||lang!==Q.lang)return;rows=result.filter(x=>x.status==='fulfilled').map(x=>x.value);previous=new Set(rows.map(x=>String(x.id)));status(rows.length?(result.some(x=>x.status==='rejected')?Q.t('notAvailable'):''):Q.t(mode==='favorites'?'noSaved':'sourceError'));render();}catch(e){if(token===seq)Q.error($('#hadithStatus'),e);}finally{if(token===seq){busy=false;controls();}}}
async function save(h){await Q.idb('put',`hadith:${h.id}:${h._language}`,h);const a=Q.saved();if(!a.includes(String(h.id))&&!Q.set('fqHadithFav',[...a,String(h.id)]))throw Error('Storage unavailable');Q.notify();}$('#hadithGrid').onclick=async e=>{const b=e.target.closest('[data-save-hadith]');if(!b)return;const id=b.dataset.saveHadith,h=rows.find(x=>String(x.id)===id);if(!h)return;b.disabled=true;try{if(Q.saved().includes(id))Q.set('fqHadithFav',Q.saved().filter(x=>x!==id));else await save(h);Q.notify();render();}catch{Q.toast(Q.t('storageError'));b.disabled=false;}};$('#saveBatch').onclick=async()=>{const batch=[...rows],b=$('#saveBatch');b.disabled=true;let count=0;try{for(const h of batch){await save(h);count++;}Q.toast(Q.t('saved')+': '+count);render();}catch{Q.toast(Q.t('saved')+': '+count+' / '+batch.length+'. '+Q.t('storageError'));}finally{controls();}};
$('#shuffleHadith').onclick=()=>load('shuffle');$('#browseHadith').onclick=()=>load('browse',1);$('#hadithFavorites').onclick=()=>load('favorites');$('#hadithPrev').onclick=()=>load(mode,page-1);$('#hadithNext').onclick=()=>load(mode,page+1);$('#hadithCategory').onchange=()=>{previous=new Set();load('browse',1);};$('#hadithFilter').oninput=render;Q.hadithFavorites=()=>{$('#hadith').scrollIntoView();return load('favorites');};window.addEventListener('fq:language',async()=>{++seq;busy=false;rows=[];previous=new Set();status('');render();await categories();if(loaded)load(mode,1);});categories();controls();})();
